def _row(size, bold):
    key = (1 if bold else 0, size)
    if key not in DIALOG:
        raise SchematicError(f"no Dialog font metrics for size {size} (measured {SIZES.start}..{SIZES.stop - 1})")
    return DIALOG[key]


def width(text, size, bold=False):
    """px JMRI gives `text` in Dialog at `size`; a character outside printable ASCII counts as the widest one."""
    adv = _row(size, bold)[1]
    widest = max(adv)
    return sum(adv[ord(c) - 32] if 32 <= ord(c) < 127 else widest for c in text)


def height(size, bold=False):
    return _row(size, bold)[0]
